import { defineSlot } from '../Slot';

/**
 * The body of the loaded sheet. Every feature kept per sheet contributes its own panel here; it
 * is rendered only once a sheet has loaded, with the signed-in user and that sheet's id.
 */
export const SheetPanel = defineSlot<{ user: string; sheetId: string }>('sheet.panel');
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { figure, ratesQuery, sumDue } from '../rates/ratesQuery';
import { useFloor, useLate } from '../settings/settingsQuery';
import { useUser } from '../session/useUser';
import { periodOf, periodsKey, periodsQuery } from './periodsQuery';
import type { Period } from './periodsQuery';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

function ClaimPeriod({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  return <td data-testid="claim-period">{periodOf(periods, claim.date)?.name ?? ''}</td>;
}

/** A period's closed flag and the buttons that close and reopen it (reopening is a steward's). A refusal
 *  shows on the period until its next action. */
function PeriodClosed({ sheetId, period }: { sheetId: string; period: Period }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const once = useSubmitOnce();
  const close = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/close`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () => setError(`The period ${period.name} could not be closed: it is already closed.`),
  });
  const reopen = useMutation({
    mutationFn: () =>
      putJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(period.name)}/reopen`,
        {},
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
    onError: () =>
      setError(`The period ${period.name} could not be reopened: it is not closed, or you are not a steward.`),
  });

  return (
    <td>
      <span data-testid="period-closed">{period.closed ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="period-close"
        disabled={close.isPending}
        onClick={() => {
          setError('');
          once(() => close.mutateAsync());
        }}
      >
        Close
      </button>{' '}
      <button
        type="button"
        data-testid="period-reopen"
        disabled={reopen.isPending}
        onClick={() => {
          setError('');
          once(() => reopen.mutateAsync());
        }}
      >
        Reopen
      </button>
      {error && <span data-testid="period-error">{error}</span>}
    </td>
  );
}

/** The sheet's periods, each with its due-total — the figures of the counting claims dated in it, fixed
 *  while the period is closed and live again once it is reopened — and the form a period is added through. */
function Periods({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const periods = useQuery(periodsQuery(sheetId));
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: Pick<Period, 'name' | 'from' | 'to'>) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setName('');
      setFrom('');
      setTo('');
    },
    onError: () => setError('The period could not be added: its name must be new and its dates must not overlap another period.'),
  });

  const list = periods.data ?? [];
  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const n = name.trim();
    const f = from.trim();
    const t = to.trim();
    if (n === '') {
      setError('A period needs a name.');
      return;
    }
    if (!DATE.test(f) || !DATE.test(t)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (t < f) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    if (list.some((p) => p.name === n)) {
      setError(`There is already a period named ${n}.`);
      return;
    }
    const overlapped = list.find((p) => p.from <= t && f <= p.to);
    if (overlapped) {
      setError(`The period overlaps ${overlapped.name}.`);
      return;
    }
    once(() => add.mutateAsync({ name: n, from: f, to: t }));
  };

  const dueTotal = (period: Period) =>
    period.closedTotal ??
    sumDue(
      claims
        .filter((c) => counts(c, people) && period.from <= c.date && c.date <= period.to)
        .map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late)),
    );

  const edit = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <section data-testid="periods">
      <h3>Periods</h3>
      <form data-testid="period-form" onSubmit={submit}>
        <label>
          Name <input data-testid="period-form-name" value={name} onChange={edit(setName)} />
        </label>{' '}
        <label>
          From <input data-testid="period-form-from" type="date" value={from} onChange={edit(setFrom)} />
        </label>{' '}
        <label>
          To <input data-testid="period-form-to" type="date" value={to} onChange={edit(setTo)} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={add.isPending}>
          Add period
        </button>
        {error && <p data-testid="period-form-error">{error}</p>}
      </form>
      {periods.isError && <p data-testid="periods-load-error">Could not load the periods.</p>}
      <table data-testid="periods-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
          </tr>
        </thead>
        <tbody>
          {list.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{dueTotal(p)}</td>
              <PeriodClosed sheetId={sheetId} period={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed period or an error never carries over to another sheet.
export const contributions = [
  ClaimCells.fill({ order: 15, Component: ClaimPeriod }),
  SheetPanel.fill({ order: 7, Component: ({ sheetId }) => <Periods key={sheetId} sheetId={sheetId} /> }),
];
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

/**
 * A sheet's period: a name unique on the sheet, `from` and `to` (yyyy-mm-dd) inclusive. Periods never overlap.
 * A closed period's due-total was fixed when it was closed (`closedTotal`; null while open).
 */
export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string | null };

/** Under the sheet's key, so re-loading the sheet re-reads its periods. */
export const periodsKey = (sheetId: string) => [...sheetKey(sheetId), 'periods'] as const;

/** The sheet's periods, by from-date. */
export const periodsQuery = (sheetId: string) => ({
  queryKey: periodsKey(sheetId),
  queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
});

/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { gradeOn, peopleQuery } from '../people/peopleQuery';
import { patronIdsOf, patronsQuery } from '../patrons/patronsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useFloor, useLate } from '../settings/settingsQuery';
import type { Person } from '../people/peopleQuery';
import { figure, rateFor, ratesQuery, sumDue } from './ratesQuery';
import type { Late, Rate } from './ratesQuery';

/**
 * A person's due-total: the sum of their counting claims' rounded figures, as each claim shows it. With no rate today and no figure it is n/a; otherwise it is the sum of the figures there are.
 */
function personDue(person: Person | undefined, people: Person[], claims: Claim[], rates: Rate[], today: string, floor: string, late: Late): string {
  if (!person) return 'n/a';
  const rate = rateFor(rates, gradeOn(person, today), today);
  const figures = claims
    .filter((c) => c.personId === person.id && counts(c, people))
    .map((c) => figure(c, rates, person, floor, late))
    .filter((d) => d !== 'n/a');
  return rate === undefined && figures.length === 0 ? 'n/a' : sumDue(figures);
}

function useSheetData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
  };
}

function ClaimDue({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { people, rates, floor, late } = useSheetData(sheetId);
  const person = people.find((p) => p.id === claim.personId);
  return <td data-testid="claim-due">{figure(claim, rates, person, floor, late)}</td>;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  return <td data-testid="person-due-total">{personDue(people.find((p) => p.id === personId), people, claims, rates, today, floor, late)}</td>;
}

/** A person's backing: their patrons' due-totals added up, skipping n/a; 0.00 with no patrons. */
function PersonBacking({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const ids = patronIdsOf(useQuery(patronsQuery(sheetId)).data ?? [], personId);
  const dues = people.filter((p) => ids.includes(p.id)).map((p) => personDue(p, people, claims, rates, today, floor, late));
  return <td data-testid="person-backing">{sumDue(dues)}</td>;
}

function DueTotal({ sheetId }: { sheetId: string }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  return (
    <p data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{sumDue(people.map((p) => personDue(p, people, claims, rates, today, floor, late)))}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  PersonHeaders.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 15, Component: PersonDueTotal }),
  PersonHeaders.fill({ order: 22, Component: () => <th>Backing</th> }),
  PersonCells.fill({ order: 22, Component: PersonBacking }),
  SheetPanel.fill({ order: 25, Component: DueTotal }),
];
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they are on hold: while held, their OPEN claims count in no live total.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean };

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
import { asFlag, useSearchParam } from '../../url/useSearchParam';

/** Whether retired people are listed, kept in the URL: off when the screen is first opened, and left as it is by loading a sheet. */
export function useShowRetired() {
  return useSearchParam('showRetired', asFlag);
}
import { getJson } from '../../api/http';
import type { Person } from '../people/peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/**
 * `amount` has two decimals ("12.50"); `date` is yyyy-mm-dd; `number` is given on opening and kept when voided (null for a draft);
 * `settledDue` is the due fixed on settling (null when not settled, or settled while no rate applied on the claim's date);
 * `openedBy` is the user who opened it (null when never opened), who cannot settle it;
 * `stated` is whether its person's last statement bound it, at `statedDue` (null when it had no figure then);
 * a negative `amount` is a correction, and `corrects` is the number of the settled claim it corrects (null for any other claim).
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: number | null;
};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * Only OPEN and SETTLED claims count toward claimed, due and every total; drafts and voided ones do not,
 * nor do the OPEN claims of a person on hold.
 */
export const counts = (c: Claim, people: Person[]) =>
  c.status === 'SETTLED' || (c.status === 'OPEN' && !people.find((p) => p.id === c.personId)?.held);

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
});

/** Amounts are added up in whole cents, so the sum shows exactly with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

